<script setup lang="ts">const route=useRoute(),slug=String(route.params.slug),{load,pending,store}=useStorefront(slug);await load();useSeoMeta({title:()=>`${store.value.display_name} | هفت‌سو`,description:()=>store.value.description,ogTitle:()=>store.value.display_name});</script><template><main id="main-content" class="storefront-page content-container"><UiState v-if="pending" kind="loading" title="در حال بارگذاری فروشگاه" description="مشخصات تأییدشده، شعب و آگهی‌ها در حال دریافت است."/><template v-else><StorefrontHero :store="store"/><section class="storefront-branches"><h2>شعب فعال</h2><article v-for="branch in store.branches" :key="branch.id"><strong>{{branch.title}}</strong><p>{{branch.address}}</p><span>{{branch.phone}}</span></article></section><section><h2>آگهی‌های این فروشگاه</h2><UiState kind="empty" title="آگهی‌های فروشگاه با فیلتر معتبر نمایش داده می‌شوند" description="فقط آگهی‌های منتشرشده و فعال قابل مشاهده‌اند."/></section></template></main></template>
